inputs = ['zwfyza', 'akydyx', 'icfgj', 'xjfz', 'vbccu']
outputs = ['zwfyzcv', 'cvkydyx', 'icfzvgvck', 'xvckfz', 'vgcvccu']

# Find changed pairs manually since we can't import the library
changed_pairs = []
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        changed_pairs.append((i, inputs[i], outputs[i]))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Let's look at patterns in the transformations
print("\nAnalyzing transformation patterns:")

# Looking at positions where changes occur
patterns = {}
for idx, inp, outp in changed_pairs:
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            if (j, inp[j], outp[j]) not in patterns:
                patterns[(j, inp[j], outp[j])] = []
            patterns[(j, inp[j], outp[j])].append((idx, inp, outp))

print("Position-based changes:")
for key, examples in patterns.items():
    print(f"  Position {key[0]}: '{key[1]}' -> '{key[2]}' occurs in {len(examples)} examples")
    for ex in examples:
        print(f"    Example {ex[0]}: '{ex[1]}' -> '{ex[2]}'")

